WITH filtered_products AS (SELECT *, UPPER(product_name) AS product_name_upper FROM products WHERE price > 690), category_summary AS (SELECT category, supplier_id, SORT_ARRAY(COLLECT_SET(brand)) AS brand_list, COUNT(CASE WHEN category = 'Sports' THEN 1 END) AS sports_count FROM filtered_products GROUP BY category, supplier_id) SELECT category, supplier_id, brand_list, sports_count FROM category_summary WHERE sports_count < 9 ORDER BY sports_count;
